25	     * Determine if the Athena service is available based on whether the corresponding profile is active
26	     */
27	    public isEnabled(): Observable<boolean> {
28	        return this.profileService.getProfileInfo().pipe(switchMap((profileInfo) => of(profileInfo.activeProfiles.includes(PROFILE_ATHENA))));
29	    }
