31	    /**
32	     * Fetches all available modules for a course and exercise.
33	     *
34	     * @param courseId The id of the course for which the feedback suggestion modules should be fetched
35	     * @param exercise The exercise for which the feedback suggestion modules should be fetched
36	     */
37	    public getAvailableModules(courseId: number, exercise: Exercise): Observable<string[]> {
38	        return this.isEnabled().pipe(
39	            switchMap((isAthenaEnabled) => {
40	                if (!isAthenaEnabled) {
41	                    return of([] as string[]);
42	                }
43	                return this.http
44	                    .get<string[]>(`${this.resourceUrl}/courses/${courseId}/${exercise.type}-exercises/available-modules`, { observe: 'response' })
45	                    .pipe(switchMap((res: HttpResponse<string[]>) => of(res.body!)));
46	            }),
47	        );
48	    }
