51	     * Get feedback suggestions for the given submission from Athena
52	     *
53	     * @param exercise
54	     * @param submissionId the id of the submission
55	     * @return observable that emits the feedback suggestions
56	     */
57	    private getFeedbackSuggestions<T>(exercise: Exercise, submissionId: number): Observable<T[]> {
58	        if (!exercise.feedbackSuggestionModule) {
59	            return of([]);
60	        }
61	        return this.isEnabled().pipe(
62	            switchMap((isAthenaEnabled) => {
63	                if (!isAthenaEnabled) {
64	                    return of([] as T[]);
65	                }
66	                return this.http
67	                    .get<T[]>(`${this.resourceUrl}/${exercise.type}-exercises/${exercise.id}/submissions/${submissionId}/feedback-suggestions`, { observe: 'response' })
68	                    .pipe(switchMap((res: HttpResponse<T[]>) => of(res.body!)));
69	            }),
70	        );
71	    }
