73	    /**
74	     * Find a grading instruction by id in the given exercise
75	     */
76	    private findGradingInstruction(exercise: Exercise, id: number): any | undefined {
77	        for (const criterion of exercise.gradingCriteria ?? []) {
78	            for (const instruction of criterion.structuredGradingInstructions) {
79	                if (instruction.id == id) {
80	                    return instruction;
81	                }
82	            }
83	        }
84	        return undefined;
85	    }
