87	    /**
88	     * Get feedback suggestions for the given text submission from Athena
89	     *
90	     * @param exercise
91	     * @param submission  the submission
92	     * @return observable that emits the referenced feedback suggestions as TextBlockRef objects
93	     * with TextBlocks and the unreferenced feedback suggestions as Feedback objects
94	     * with the "FeedbackSuggestion:" prefix
95	     */
96	    public getTextFeedbackSuggestions(exercise: Exercise, submission: TextSubmission): Observable<(TextBlockRef | Feedback)[]> {
97	        return this.getFeedbackSuggestions<TextFeedbackSuggestion>(exercise, submission.id!).pipe(
98	            map((suggestions) => {
99	                // Convert referenced feedback suggestions to TextBlockRefs for easier handling in the components
100	                return suggestions.map((suggestion) => {
101	                    const feedback = new Feedback();
102	                    feedback.credits = suggestion.credits;
103	                    // Text feedback suggestions are automatically accepted, so we can set the text directly:
104	                    feedback.text = FEEDBACK_SUGGESTION_ACCEPTED_IDENTIFIER + suggestion.title;
105	                    feedback.detailText = suggestion.description;
106	                    // Load grading instruction from exercise, if available
107	                    if (suggestion.structuredGradingInstructionId != undefined) {
108	                        feedback.gradingInstruction = this.findGradingInstruction(exercise, suggestion.structuredGradingInstructionId);
109	                    }
110	                    if (suggestion.indexStart == null) {
111	                        // Unreferenced feedback, return Feedback object
112	                        feedback.type = FeedbackType.MANUAL_UNREFERENCED;
113	                        return feedback;
114	                    }
115	                    // Referenced feedback, convert to TextBlockRef
116	                    feedback.type = FeedbackType.MANUAL;
117	                    const textBlock = new TextBlock();
118	                    textBlock.startIndex = suggestion.indexStart;
119	                    textBlock.endIndex = suggestion.indexEnd;
120	                    textBlock.setTextFromSubmission(submission);
121	                    feedback.reference = textBlock.id;
122	                    return new TextBlockRef(textBlock, feedback);
123	                });
124	            }),
125	        );
126	    }
